function wooCommerceOrderNotice(input) {
  const order = input.order;
  if (!order || typeof order !== 'object' || Array.isArray(order) || !order.billing || typeof order.billing !== 'object' || typeof order.billing.first_name !== 'string' || !Array.isArray(order.line_items) || !order.line_items[0] || typeof order.line_items[0].name !== 'string') throw new Error('The order needs billing.first_name and the first line item name before notifying Mattermost');
  if (typeof input.channelId !== 'string' || !/^[a-z0-9]{26}$/.test(input.channelId)) throw new Error('Set the 26-character Mattermost channel ID');
  return { order, channelId: input.channelId, message: order.billing.first_name + ' bought ' + order.line_items[0].name + '!' };
}

return $input.all().map(item=>({json:wooCommerceOrderNotice({order:item.json,channelId:"YOUR_MATTERMOST_CHANNEL_ID"})}));

function wooCommerceMattermostReceipt(input) {
  const post = input.post;
  if (!post || typeof post !== 'object' || Array.isArray(post) || typeof post.id !== 'string' || !/^[a-z0-9]{26}$/.test(post.id) || post.channel_id !== input.channelId || post.message !== input.message) throw new Error('Mattermost did not confirm the expected post. It may already have accepted it; inspect the channel before replaying.');
  return { order: input.order, post, rawPost: input.rawPost };
}

const prepared=$("Build the purchase notice").all();return $input.all().map((item,index)=>({json:wooCommerceMattermostReceipt({...prepared[index].json,post:item.json,rawPost:item.json})}));
